#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Integrate the approved station-input and statehood decisions into MMOSON_v7.docx.

This is a text-only integration. No images or drawings are generated.
"""
from __future__ import annotations
from copy import deepcopy
from pathlib import Path
import sys
from docx import Document

ROOT = Path(__file__).resolve().parents[1]
DOC = ROOT / 'MMOSON_v7.docx'


def set_text(p, text):
    rpr = deepcopy(p.runs[0]._r.rPr) if p.runs and p.runs[0]._r.rPr is not None else None
    for r in list(p.runs):
        r._element.getparent().remove(r._element)
    r = p.add_run(text)
    if rpr is not None:
        r._r.insert(0, deepcopy(rpr))


def one_prefix(doc, prefix):
    hits = [p for p in doc.paragraphs if p.text.startswith(prefix)]
    if len(hits) != 1:
        raise RuntimeError(f'{prefix!r}: expected 1, found {len(hits)}')
    return hits[0]


def replace_prefix(doc, prefix, text):
    set_text(one_prefix(doc, prefix), text)


def insert_before(anchor, text, style=None):
    p = anchor.insert_paragraph_before(text)
    if style is not None:
        p.style = style
    return p


def main(path=DOC):
    doc = Document(path)

    # Reconcile the existing legal chapter with the adopted contractual path.
    replace_prefix(doc, 'Ответ отрицательный, и он не зависит от желания учредителей.',
        'Одностороннее провозглашение не создаёт государство автоматически. В текущем правовом режиме станция остаётся зарегистрированным космическим объектом, а космическое пространство и небесные тела не становятся территорией ММОСО\'Н. Долгосрочная цель проекта, однако, состоит не в декларации без оснований, а в договорном переходе к государственности после формирования постоянного населения, органов власти, собственной правовой системы и способности выполнять внешние обязательства.')
    replace_prefix(doc, 'Попытка провозгласить суверенитет привела бы',
        'Попытка провозгласить суверенитет без договора и признания привела бы не к немедленному появлению государства, а к конфликту с государством регистрации и международными обязательствами по космическому объекту. Поэтому переход должен быть поэтапным: операторская администрация, переходная автономия, конституционное самоуправление, затем заявление о государственности и запрос признания.')
    replace_prefix(doc, 'Правильная форма — не государство, а международный консорциум',
        'Практическая форма на ранних этапах — международный консорциум с государством регистрации и договорной юрисдикцией. Целевая форма после переходного периода — ММОСО\'Н как отдельное государство с полным внутренним суверенитетом. Собственный суверенитет относится к управлению станцией, её жителями, инфраструктурой и внутренними системами; он не означает присвоения космического пространства или астероидов.')
    replace_prefix(doc, 'Ответ прямой: по законам государства регистрации.',
        'До договорного перехода жители живут по праву государства регистрации и локальным нормативным актам оператора. По мере создания органов автономии локальное право преобразуется в собственное право ММОСО\'Н, согласованное с международными обязательствами и договорами с государством регистрации. Земные кодексы не применяются автоматически после перехода: они действуют только в пределах прямой рецепции или договора.')

    # Update the existing solar/antenna paragraphs.
    replace_prefix(doc, 'Реакторы размещаются на задней неподвижной ферменной раме',
        'Реакторы размещаются на задней неподвижной ферменной раме позади задних торцов, вне внутреннего пространства цилиндров. На задних рамах размещаются шесть вспомогательных солнечных крыльев — по три на каждый цилиндр; три крыла каждой рамы образуют локальную симметричную триаду с угловым шагом 120°. Ровно три антенных модуля распределены по схеме 2 + 1: два на задней раме первого цилиндра и один на задней раме второго; два первых размещаются зеркально, одиночный получает локальный противовес или сервисный контейнер. На боковой обшивке цилиндров ничего не размещается.')
    replace_prefix(doc, 'Солнечные батареи являются отдельным вспомогательным источником',
        'Солнечные батареи являются отдельным вспомогательным источником на шести поворотных раскрывающихся крыльях неподвижных задних рам — по три на цилиндр. Суммарная площадь 586,8 км² сохраняется, площадь одного крыла составляет около 97,8 км², расчётная мощность — около 8,9 ГВт. Крылья не создают солнечного режима освещения и не заменяют реакторы: ОСБ остаются единственным источником света, а установка удержания работает независимо от выработки крыльев. При отказе одного крыла остаётся 83,3 % вспомогательной мощности.')
    replace_prefix(doc, 'Площадь и мощность. Собираемая мощность определяется',
        'Площадь и мощность. Собираемая мощность определяется площадью проекции батарей на направление луча. Суммарная площадь шести задних крыльев принимается 586,8 км², то есть по 97,8 км² на крыло и по 293,4 км² на заднюю раму цилиндра. При солнечной постоянной в точке L1 1 361 Вт/м², КПД фотопреобразователей 25 % и коэффициенте заполнения 0,268 собирается 53,4 ГВт — 7,41 % электрической мощности станции.')
    replace_prefix(doc, 'Устройство крыла. Каждое крыло собрано',
        'Устройство крыла. Каждое из шести крыльев собрано из складных секций, раскрывающихся после выведения наподобие гармошки; в сложенном виде крыло убирается к заднему узлу. Крыло опирается на моторизованный поворотный шарнир с двумя степенями свободы, размещённый на невращающейся части задней рамы. Три шарнира одной рамы разнесены по локальному азимуту на 120°.')
    replace_prefix(doc, 'Расчётная площадь принимается равной 586,8 км²',
        'Расчётная площадь шести задних крыльев принимается равной 586,8 км², то есть по 97,8 км² на крыло. При постоянном наведении на светило вся площадь работает как проекция, и собираемая мощность составляет 53,4 ГВт. Масса при удельной 2 кг/м² — 1,17 млн т, 0,0025 % массы станции; в массовом балансе (п. 4.3) не отражается.')

    # Replace the old settlement paragraph with the adopted coordinate basis.
    replace_prefix(doc, 'Расселение принимается не сплошным, а очаговым:',
        'Расселение принимается не сплошным, а очаговым: на каждый цилиндр предусматривается 12 поселений по 40–45 тысяч жителей. Для генеральной карты вводится сетка из трёх продольных полос и четырёх азимутальных секторов. Предварительные координаты продольных полос — x = 5, 13 и 20 км от начала цилиндрической части; азимуты узлов — 0°, 90°, 180° и 270°. Все узлы находятся в климатических зонах I–II. На один узел приходится ориентировочно 15,75 км² застройки, 57,6 км² сельхозугодий, 20,9 км² леса и парков и 10,5 км² водоёмов и технических зон. Внутренняя сеть включает четыре продольные магистрали, девять кольцевых линий, грузовой обход и подземные инженерные коллекторы.')

    # Add technical station layout subsection before 4.7.7.
    anchor = one_prefix(doc, '4.7.7. Обмен моментом импульса при перевозках')
    insert_before(anchor, '4.7.7.1. Компоновочная база передней рамы и причального портала', anchor.style)
    body_style = one_prefix(doc, 'Расчёт пропускной способности: в каждом коридоре').style
    insert_before(anchor, 'Для каждого цилиндра принимается отдельная комбинированная передняя рама: силовое кольцо подшипника Ø400 м, 24 радиальных коробчатых силовых элемента с шагом 15°, центральный транспортный модуль около 74 × 74 м и внешний причально-сервисный портал. Радиальная ферма и портал не соединяются с боковой оболочкой; силовой путь замыкается через переднюю цапфу и корпус подшипника.', body_style)
    insert_before(anchor, 'Причальный портал каждого цилиндра имеет шесть мест: четыре универсальных пассажирско-грузовых, одно стерильное грузовое и одно сервисно-аварийное. Расчёт основан на карантинном потоке 100 000 человек в год, трёхкратном пике и консервативном внешнем модуле на 50 пассажиров с оборотом до 8 часов. Четыре пассажирских места дают резерв N+1 относительно пикового потока; шахты с пропускной способностью 1 350 человек в час на цилиндр не являются ограничивающим звеном.', body_style)
    insert_before(anchor, 'Внешняя боковая оболочка обоих цилиндров остаётся гладкой. Внешний общий вид показывает только физические рамы, причалы, радиаторы, шесть солнечных крыльев и ровно три антенны; разрезы транспортного узла выпускаются отдельными техническими видами.', body_style)

    # Add internal map subsection before 12.6.
    anchor = one_prefix(doc, '12.6. Водоснабжение и канализация')
    insert_before(anchor, '12.5.1. Координатная база внутренней карты поселений', anchor.style)
    body_style = one_prefix(doc, 'Поверхность 1 257 км² на цилиндр').style
    insert_before(anchor, 'Для первого генерального плана каждый цилиндр делится на 12 городских узлов: три продольные полосы x = 5, 13 и 20 км и четыре азимутальных сектора φ = 0°, 90°, 180° и 270°. Узлы соединяются четырьмя продольными магистралями и девятью кольцевыми линиями с шагом около 5 км по оси. Внешний вход от коридоров А и Б соединяется с двумя передними пересадочными узлами; грузовой поток имеет отдельный обход.', body_style)
    insert_before(anchor, 'Площадь одного узла в первом приближении: 15,75 км² застройки, 57,6 км² сельхозугодий, 20,9 км² леса и парков и 10,5 км² водоёмов и технических зон. Это зонировочная карта, а не окончательная планировка отдельных зданий; точная трассировка сетей и границ кварталов остаётся следующим этапом.', body_style)

    # Add statehood model before chapter 14.
    anchor = one_prefix(doc, '14. АВАРИЙНЫЕ РЕЖИМЫ, РЕСУРС КОНСТРУКЦИИ')
    hstyle = anchor.style
    insert_before(anchor, '13.6. Целевая модель государственности ММОСО\'Н', hstyle)
    body_style = one_prefix(doc, 'Практический вывод. Ближайшие правовые действия').style
    insert_before(anchor, 'ММОСО\'Н проектируется как отдельное государство с полным внутренним суверенитетом. Это целевая политико-правовая модель, а не односторонняя декларация и не юридическое заключение. Полный внутренний суверенитет означает собственные конституцию, каталог основных прав, законодательную, исполнительную и судебную ветви власти, бюджет, налоги, режим безопасности, гражданскую оборону и аварийное управление. Суверенитет относится к станции, её жителям, инфраструктуре и внутренним системам; космическое пространство и астероиды не объявляются собственностью ММОСО\'Н.', body_style)
    insert_before(anchor, '13.7. Двойной контур гражданства', hstyle)
    insert_before(anchor, 'Гражданство ММОСО\'Н является самостоятельным политико-правовым статусом и не требует автоматического отказа от исходного гражданства Земли. Постоянный житель получает путь к натурализации через срок проживания, знание конституции и правил станции, гражданскую присягу и проверку дееспособности. Происхождение, рождение и семейная связь могут давать упрощённую регистрацию; произвольное лишение гражданства запрещается, а выход возможен при наличии другого правового статуса. Автоматическое гражданство по рождению, минимальный срок натурализации и статус детей смешанных семей устанавливаются будущей конституцией.', body_style)
    insert_before(anchor, '13.8. Гибридная правовая система', hstyle)
    insert_before(anchor, 'Основой становится собственная конституция ММОСО\'Н, согласованная с обязательными нормами международного права. Собственное право регулирует жизнедеятельность замкнутой станции, труд, жильё, медицину, образование, социальные гарантии, распределение ресурсов, налоги, промышленность, безопасность, выборы, чрезвычайное положение и суды. Земные кодексы не применяются автоматически: они действуют только если включены в право ММОСО\'Н законом о рецепции или международным договором. Обязательны независимый суд, судебный пересмотр администрации, омбудсмен, прозрачный бюджет, право на адвоката, запрет коллективной ответственности и ограниченное по сроку чрезвычайное положение.', body_style)
    insert_before(anchor, '13.9. Договорный путь к признанию', hstyle)
    insert_before(anchor, 'Переход выполняется поэтапно: соглашение о переходной автономии с государством или коалицией, отвечающей за запуск и регистрацию; временная хартия и перепись постоянного населения; создание выборных органов; конституционное собрание и принятие конституции; двусторонние соглашения о юрисдикции, гражданстве, спасении, торговле, обороне и ответственности за космический объект; затем заявление о государственности и запрос международного признания. До признания станция сохраняет договорную связь с государством регистрации и не объявляет космическую среду своей территорией.', body_style)
    insert_before(anchor, '13.10. Переходные этапы управления', hstyle)
    insert_before(anchor, 'Этап I — операторская администрация с хартией прав жителей. Этап II — автономия с избираемым советом, исполнительной администрацией, судом или трибуналом и независимым инспектором безопасности. Этап III — конституционное государство с постоянными органами власти и договорным процессом признания. Этап IV — признанное государство, самостоятельно ведущее внешние отношения в пределах действующих договоров и несущее международную ответственность.', body_style)
    insert_before(anchor, '13.11. Открытые правовые вопросы', hstyle)
    insert_before(anchor, 'Нерешёнными остаются государство регистрации и распределение юрисдикции, валюта и налоговая база, собственность на инфраструктуру, оборона и пределы вооружённой силы, уголовная юрисдикция над иностранцами, трудовое, семейное и наследственное право, миграция и карантин, передача власти в аварийном режиме, допустимые формы экономики и внешний контроль безопасности. Международное признание остаётся политическим решением других государств и не гарантируется одним выполнением формальных критериев.', body_style)

    # Update the unresolved list to reference integrated decisions rather than external drafts.
    replace_prefix(doc, 'Компоновочная база транспортного интерфейса считается закрытой',
        'Компоновочная база транспортного интерфейса, комбинированной передней рамы, причальных порталов, шести солнечных крыльев, трёхантенной схемы и координатной основы внутренней карты считается закрытой на уровне текстового проектного решения; описание находится в главах 4, 7, 12 и 13 настоящего документа. Следующие проверки остаются обязательными: динамика магнитного подшипника Ø400 м, посадка на механические ловители, МКЭ усиления устьев Ø30 м, ресурс сегментированных уплотнений, тепловое расширение перехода, прочность крыльев, продольная динамика полной кабины массой 15 т, тормозной путь и радиационная защита закрытой трассы. Отдельные текстовые спецификации по этим решениям не являются частью проекта и не создаются.')

    doc.save(path)
    print('UPDATED', path)


if __name__ == '__main__':
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else DOC)
